import{_ as r,b as a,c as t,g as o}from"./chunks/framework.86O3EbG5.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"articles/books/how-program-works/4.md","filePath":"articles/books/how-program-works/4.md"}'),p={name:"articles/books/how-program-works/4.md"};function s(n,e,_,m,l,c){return a(),t("div",null,[...e[0]||(e[0]=[o('<p>程序文件存储在硬盘中；执行时先进入内存，CPU 从内存中读取指令和数据来完成取指、译码、执行。</p><p>资料</p><p><a href="https://man7.org/linux/man-pages/man5/elf.5.html" target="_blank" rel="noreferrer">https://man7.org/linux/man-pages/man5/elf.5.html</a></p><h3 id="如何将程序从磁盘加载进内存" tabindex="-1">如何将程序从磁盘加载进内存</h3><p>对于 c 程序，编译后可得到一个<code>.out</code>的文件，该文件在 Linux 中是按照 ELF 规范生成的。</p><p>程序加载器会读取 ELF 标准的文件，解析 Program Headers，操作系统为该文件程序分配虚拟地址空间。</p><p>分配虚拟地址空间，不代表程序被完整的加载进内存，当第一次访问某页时，如果该页不在物理内存中，CPU会触发缺页异常，内核进行处理，检测访问合法性、从磁盘读取或复用缓存等。更新页表，并重新执行指令。</p><p>（这里需要看 x86 的实现）</p>',8)])])}const f=r(p,[["render",s]]);export{d as __pageData,f as default};
